}""","""export interface EligibleSample {
    actionId: string;
    agent: string;
    completedAt: string;
    /** The run's duration split; null members mean it was recorded before the split existed. */
    durationSplit: StatsDurationComponents;
    metricValue: number;
    model: string;
    status: 'cancelled' | 'completed' | 'failed';
}""",1)

s=s.replace("""        samples.push({
            actionId: conversation.actionId!,
            agent: conversation.agent!,
